/**
 * Ornament art, ported from Pixel Frame `corners.js`. Simple pieces are hand-drawn ASCII; round or
 * organic ones are generated by small functions that emit the same ASCII format.
 */
import { parseArt } from './bitmap.ts';
import type { Art, ArtDef } from './bitmap.ts';

export type OrnamentSize = 'small' | 'medium' | 'large';
/** Size factor per ornament size; medium reproduces the hand-tuned originals. */
export const ORNAMENT_SIZES: Readonly<Record<OrnamentSize, number>> = { small: 0.75, medium: 1, large: 1.4 };

type Cell = readonly [string, string] | null;

const digit = (v: number) => String(Math.max(0, Math.min(9, Math.round(v))));
const odd = (v: number) => 2 * Math.round((v - 1) / 2) + 1;

function gen(w: number, h: number, fn: (x: number, y: number) => Cell): { height: string[]; mat: string[] } {
  const height: string[] = [];
  const mat: string[] = [];
  for (let y = 0; y < h; y++) {
    let hr = '';
    let mr = '';
    for (let x = 0; x < w; x++) {
      const r = fn(x, y);
      hr += r ? r[0] : '.';
      mr += r ? r[1] || '.' : '.';
    }
    height.push(hr);
    mat.push(mr);
  }
  return { height, mat };
}

type Point = readonly [number, number];

/** Remove "L-corner" pixels from a rasterised path (pixel-perfect lines). */
function pixelPerfect(points: readonly Point[]): Point[] {
  const out: Point[] = [];
  for (const p of points) {
    const last = out[out.length - 1];
    if (last && last[0] === p[0] && last[1] === p[1]) continue;
    out.push(p);
    if (out.length >= 3) {
      const a = out[out.length - 3]!, b = out[out.length - 2]!, c = out[out.length - 1]!;
      const diag = Math.abs(a[0] - c[0]) === 1 && Math.abs(a[1] - c[1]) === 1;
      if (diag && (b[0] === a[0] || b[1] === a[1])) out.splice(out.length - 2, 1);
    }
  }
  return out;
}

function line(x0: number, y0: number, x1: number, y1: number): Point[] {
  const pts: Point[] = [];
  const steps = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0));
  for (let s = 0; s <= steps; s++) pts.push([Math.round(x0 + ((x1 - x0) * s) / steps), Math.round(y0 + ((y1 - y0) * s) / steps)]);
  return pts;
}

/** Rotate upright pixel art 45 degrees so "up" points to the top-left corner. */
function rotate45(rows: readonly string[], matOf: (ch: string) => string): { height: string[]; mat: string[] } {
  const h = rows.length;
  const w = rows[0]!.length;
  const half = (w - 1) / 2;
  const at = (c: number, r: number): string | null => {
    const col = c + half;
    if (r < 0 || r >= h || col < 0 || col >= w || !Number.isInteger(r) || !Number.isInteger(col)) return null;
    const ch = rows[r]![col]!;
    return ch !== '.' ? ch : null;
  };
  const size = 2 * half + h;
  return gen(size, size, (x, y) => {
    const X = x - half;
    const Y = y - half;
    if ((X + Y) % 2 === 0) {
      const ch = at((X - Y) / 2, (X + Y) / 2);
      return ch ? ['#', matOf(ch)] : null;
    }
    const r = (X + Y) / 2;
    const c = (X - Y) / 2;
    const around = [at(c - 0.5, r - 0.5), at(c + 0.5, r + 0.5), at(c - 0.5, r + 0.5), at(c + 0.5, r - 0.5)].filter((v): v is string => v !== null);
    return around.length >= 2 ? ['#', matOf(around[0]!)] : null;
  });
}

const RIVET_BOSS = ['1222221', '2444442', '2456542', '2467642', '2456542', '2444442', '1222221'];

const FLEUR: Readonly<Record<OrnamentSize, readonly string[]>> = {
  small: [
    '....#....',
    '...###...',
    '..#####..',
    '..#####..',
    '.#.###.#.',
    '##.###.##',
    '#..###..#',
    '#..###..#',
    '.BBBBBBB.',
  ],
  medium: [
    '......#......',
    '.....###.....',
    '.....###.....',
    '....#####....',
    '....#####....',
    '.##..###..##.',
    '####.###.####',
    '#..#.###.#..#',
    '#...#####...#',
    '.#..#####..#.',
    '.BBBBBBBBBBB.',
  ],
  large: [
    '........#........',
    '.......###.......',
    '.......###.......',
    '......#####......',
    '......#####......',
    '.....#######.....',
    '..##..#####..##..',
    '.####..###..####.',
    '##..##.###.##..##',
    '#....#.###.#....#',
    '#.....#####.....#',
    '.#...#######...#.',
    '..#..#######..#..',
    '.BBBBBBBBBBBBBBB.',
  ],
};
const sizeName = (f: number): OrnamentSize => (f < 1 ? 'small' : f > 1 ? 'large' : 'medium');

const makers: Record<string, (f: number) => ArtDef> = {
  /** 1-px notch: clears the outermost corner pixel. */
  notch: () => ({ name: 'Notch', ox: 0, oy: 0, height: ['x'] }),

  rivetBoss: f => {
    if (f === 1) return { name: 'Rivet boss', ox: 1, oy: 1, defaultMat: 'a', height: RIVET_BOSS };
    const n = odd(7 * f);
    const c = (n - 1) / 2;
    return {
      name: 'Rivet boss', ox: Math.round(f), oy: Math.round(f), defaultMat: 'a',
      ...gen(n, n, (x, y) => {
        const r = Math.max(Math.abs(x - c), Math.abs(y - c));
        const e = Math.hypot(x - c, y - c);
        if (r === c) return [Math.abs(x - c) === c && Math.abs(y - c) === c ? '1' : '2', 'a'];
        if (r === c - 1) return ['4', 'a'];
        return [digit(4 + 3 * (1 - e / Math.max(1, c - 1))), 'a'];
      }),
    };
  },

  /** Square stepped boss for the double rail. */
  squareBoss: f => {
    const n = odd(11 * f);
    const c = (n - 1) / 2;
    return {
      name: 'Square boss', ox: Math.round(2 * f), oy: Math.round(2 * f),
      ...gen(n, n, (x, y) => {
        const t = Math.max(Math.abs(x - c), Math.abs(y - c)) / c;
        const h = t >= 0.99 ? 1 : t >= 0.79 ? 3 : t >= 0.39 ? 4 : t >= 0.19 ? 5 : 6;
        return [String(h), t <= 0.21 ? 'm' : 'a'];
      }),
    };
  },

  /** Riveted plate corner: flat plate with a domed rivet. */
  plateCorner: f => {
    const n = odd(9 * f);
    const c = (n - 1) / 2;
    const rr = 1.5 * f;
    return {
      name: 'Plate corner', ox: Math.round(f), oy: Math.round(f),
      ...gen(n, n, (x, y) => {
        const r = Math.max(Math.abs(x - c), Math.abs(y - c));
        const e = Math.hypot(x - c, y - c);
        if (e <= rr) return [digit(5 - e / f), 'a'];
        return [r === c ? '1' : r === c - 1 ? '2' : '3', 'm'];
      }),
    };
  },

  /** Square boss with a cabochon gem that lights up on focus / active. */
  gemBoss: f => {
    const n = odd(13 * f);
    const c = (n - 1) / 2;
    const gr = 2.6 * f;
    const bezel = Math.ceil(gr);
    return {
      name: 'Gem boss', ox: Math.round(4 * f), oy: Math.round(4 * f),
      ...gen(n, n, (x, y) => {
        const r = Math.max(Math.abs(x - c), Math.abs(y - c));
        const e = Math.hypot(x - c, y - c);
        if (e <= gr) return [digit(9 - (e * 1.5) / f), 'g'];
        if (r === c) return ['1', 'a'];
        if (r === c - 1) return ['3', 'a'];
        if (r === bezel) return ['5', 'a'];
        return ['4', 'a'];
      }),
    };
  },

  /** Rosette / compass: eight rounded petals, the four cardinal points reach further. */
  rosette: f => {
    const n = odd(15 * f);
    const c = (n - 1) / 2;
    return {
      name: 'Rosette', ox: c - 2, oy: c - 2,
      ...gen(n, n, (x, y) => {
        const dx = x - c;
        const dy = y - c;
        const e = Math.hypot(dx, dy);
        const c4 = Math.cos(4 * Math.atan2(dy, dx));
        const R = f * (4.4 + 1.5 * Math.abs(c4) + 1.3 * Math.pow(Math.max(0, c4), 6));
        if (e > R) return null;
        if (e <= 2.1 * f) return [digit(8 - (e * 1.4) / f), 'g'];
        const petal = 0.55 + 0.45 * Math.abs(c4);
        return [digit(1 + 4 * (1 - e / R) * petal + (e < 3 * f ? 1 : 0)), 'a'];
      }),
    };
  },

  /** Fleur-de-lis standing on each corner as a finial. */
  fleur: f => {
    const rows = FLEUR[sizeName(f)];
    const w = rows[0]!.length;
    return {
      name: 'Fleur-de-lis', ox: (w - 1) / 2 - 2, oy: rows.length - 1, autoCap: 3, autoBase: 1,
      ...gen(w, rows.length, (x, y) => {
        const ch = rows[y]![x]!;
        return ch === '.' ? null : ch === 'B' ? ['2', 'm'] : ['#', 'a'];
      }),
    };
  },

  fleurDiagonal: f => {
    const rows = FLEUR[sizeName(f)];
    const half = (rows[0]!.length - 1) / 2;
    return { name: 'Fleur-de-lis (diagonal)', ox: half + 3, oy: half + 3, autoCap: 3, autoBase: 1, ...rotate45(rows, ch => (ch === 'B' ? 'm' : 'a')) };
  },

  /** Filigree: thin 1-px scrolls. */
  scroll: f => {
    const size = Math.round(16 * f);
    const c = Math.round(6 * f);
    const pts: Point[] = [];
    const cx = c + 5.5 * f;
    const cy = c - 3.5 * f;
    let end: Point = [c, c];
    for (let a = 0; a <= Math.PI * 2.3; a += 0.03) {
      const r = 0.6 + 0.42 * f * a;
      const p: Point = [Math.round(cx + r * Math.cos(Math.PI + a)), Math.round(cy - r * Math.sin(Math.PI + a))];
      pts.push(p);
      end = p;
    }
    const path = pixelPerfect(pts.concat(line(end[0], end[1], c - 1, c - 1)));
    const set = new Set<string>();
    for (const [x, y] of path) {
      if (x >= 0 && y >= 0 && x < size && y < size) {
        set.add(`${x},${y}`);
        set.add(`${y},${x}`);
      }
    }
    const b = c - 2;
    return {
      name: 'Filigree scroll', ox: c, oy: c,
      ...gen(size, size, (x, y) => {
        if (Math.abs(x - b) + Math.abs(y - b) <= (f > 1 ? 2 : 1)) return ['3', 'g'];
        return set.has(`${x},${y}`) ? ['2', 'a'] : null;
      }),
    };
  },

  /** Centre medallion for long edges (11-slice): oval plate with a gem. */
  medal: f => {
    const w = odd(17 * f);
    const h = odd(9 * f);
    const cx = (w - 1) / 2;
    const cy = (h - 1) / 2;
    return {
      name: 'Medallion',
      ...gen(w, h, (x, y) => {
        const dx = x - cx;
        const dy = y - cy;
        const e = (dx / (8.4 * f)) ** 2 + (dy / (4.5 * f)) ** 2;
        if (e > 1) return null;
        const g = (dx / (3.2 * f)) ** 2 + (dy / (2.2 * f)) ** 2;
        if (g <= 1) return [digit(5 + (1 - g) * 3), 'g'];
        return [digit(1 + 3.2 * (1 - e)), 'a'];
      }),
    };
  },

  rivet: f => ({ name: 'Rivet', defaultMat: 'a', height: f > 1 ? ['.343.', '35553', '35753', '35553', '.343.'] : ['.4.', '454', '.4.'] }),

  /** Tiny rivet just inside each corner (negative ox/oy = starts inside the box). */
  cornerRivet: () => ({ name: 'Corner rivet', ox: -1, oy: -1, defaultMat: 'a', height: ['.3.', '353', '.3.'] }),

  /** Gem set into a slider knob. */
  knobGem: f => ({ name: 'Knob gem', defaultMat: 'g', height: f > 1 ? ['.575.', '57975', '79997', '57975', '.575.'] : ['.6.', '686', '.6.'] }),
};

export const ART_NAMES: readonly string[] = Object.keys(makers);

const cache = new Map<string, Art>();

/**
 * Register art from outside the built-in library (RPGameworks skin bake, decision 0013: a recipe's PNG art).
 * The same piece is used at every ornament size. Re-registering a name replaces it.
 */
export function defineArt(name: string, def: ArtDef): void {
  makers[name] = () => def;
  for (const key of [...cache.keys()]) if (key.startsWith(`${name}@`)) cache.delete(key);
}

/**
 * Register `<name>#accent`: the same piece at every size with its metal pixels turned to accent (RPGameworks skin
 * bake, a recipe piece with material "accent"). Gem, dark and neutral pixels keep their material. Returns the new name.
 */
export function defineAccentVariant(name: string): string {
  const make = makers[name];
  if (!make) throw new Error(`Unknown art "${name}"`);
  const variant = `${name}#accent`;
  makers[variant] = (f) => {
    const def = make(f);
    const fallback = def.defaultMat ?? 'a';
    const mat = def.height.map((row, y) => [...row].map((_, x) => {
      const m = def.mat?.[y]?.[x];
      const resolved = m !== undefined && m !== '.' ? m : fallback;
      return resolved === 'm' ? 'a' : resolved;
    }).join(''));
    return { ...def, mat, defaultMat: 'a' };
  };
  for (const key of [...cache.keys()]) if (key.startsWith(`${variant}@`)) cache.delete(key);
  return variant;
}

/** The parsed art piece, cached per size. Unknown names return null. */
export function getArt(name: string, size: OrnamentSize = 'medium'): Art | null {
  const key = `${name}@${size}`;
  let art = cache.get(key);
  const make = makers[name];
  if (!art && make) {
    art = parseArt(make(ORNAMENT_SIZES[size]));
    cache.set(key, art);
  }
  return art ?? null;
}

/** The text definition of an art piece at a size, for printing and round-trip tests. */
export function artDef(name: string, size: OrnamentSize = 'medium'): ArtDef | null {
  const make = makers[name];
  return make ? make(ORNAMENT_SIZES[size]) : null;
}
